-- СГЕНЕРИРОВАНО scripts/make-seed.mjs из src/data.js — руками не править.
-- Запуск: Supabase → SQL Editor → вставить → Run (после schema.sql).

insert into public.tours
  (id, category, type, title, place, duration, price, rating, reviews, badge, langs, images,
   lat, lng, free_cancel, group_size, meeting, description, highlights, includes, i18n, published, sort)
values
  ('pottery', 'practices', 'Мастер-класс', 'Гончарная практика: пиала своими руками', 'Мастерская Старого города', '2 часа', 18, 4.9, 186, 'Практика', 'RU · KY', array['https://images.unsplash.com/photo-1610701596007-11502861dcfa?w=900&q=80']::text[], 40.5294, 72.7918, true, 'до 8 человек', 'Мастерская на ул. Курманжан Датка', 'Местный гончар покажет, как крутить пиалу на круге. Вы унесёте своё изделие — практика, а не лекция.', array['Работа за гончарным кругом', 'История ошской керамики', 'Изделие с собой']::text[], array['Глина и обжиг', 'Фартук', 'Чай']::text[], '{"en":{"title":"Pottery workshop: make your own piala","type":"Workshop","place":"Old Town workshop","badge":"Hands-on","group":"up to 8 people","meeting":"Workshop on Kurmanjan Datka St.","description":"A local potter shows you how to throw a piala bowl on the wheel. You take your piece home — hands-on, not a lecture.","highlights":["Work at the potter''s wheel","History of Osh ceramics","Take your bowl home"],"includes":["Clay and firing","Apron","Tea"]}}'::jsonb, true, 10),
  ('cooking', 'food', 'Мастер-класс', 'Кулинарная практика: самса и лагман', 'Дом у Джаймы', '3 часа', 29, 4.8, 412, 'Практика', 'RU · EN', array['https://images.unsplash.com/photo-1555939594-58d7cb561ad1?w=900&q=80']::text[], 40.5238, 72.7974, true, 'до 10 человек', 'Вход на Базар Джайма, южные ворота', 'Готовите с семьёй повара: тесто, начинка, лагман. Потом едите то, что сделали сами, на дворике.', array['Готовите сами, не смотрите со стороны', 'Рецепты с собой', 'Обед включён']::text[], array['Продукты', 'Обед и чай', 'Рецепты PDF']::text[], '{"en":{"title":"Cooking class: samsa and lagman","type":"Workshop","place":"House near Jayma","badge":"Hands-on","group":"up to 10 people","meeting":"Jayma Bazaar, south gate","description":"Cook with a chef''s family: dough, filling, lagman noodles. Then eat what you made in the courtyard.","highlights":["You cook, not just watch","Recipes to take home","Lunch included"],"includes":["Ingredients","Lunch and tea","PDF recipes"]}}'::jsonb, true, 20),
  ('photo-walk', 'practices', 'Практика', 'Фотопрактика: золотой час в Старом городе', 'Старый город', '2.5 часа', 16, 4.7, 98, 'Практика', 'RU · EN', array['https://images.unsplash.com/photo-1469854523086-cc02fe5d8800?w=900&q=80']::text[], 40.529, 72.791, true, 'до 6 человек', 'Площадь у южных ворот', 'Короткий маршрут с фотографом: свет, кадр, люди на улице. Телефон или камера — без разницы.', array['Разбор 10 ваших кадров', 'Точки с лучшим светом', 'Малая группа']::text[], array['Гид-фотограф', 'Маршрут', 'Заметки по съёмке']::text[], '{"en":{"title":"Photo walk: golden hour in the Old Town","type":"Workshop","place":"Old Town","badge":"Hands-on","group":"up to 6 people","meeting":"Square by the south gate","description":"A short walk with a photographer: light, framing, street life. Phone or camera — either works.","highlights":["Review of 10 of your shots","Spots with the best light","Small group"],"includes":["Photographer guide","Route","Shooting notes"]}}'::jsonb, true, 30),
  ('sulaiman', 'tours', 'Экскурсия', 'Восход на Сулайман-Тоо с местным гидом', 'Сулайман-Тоо', '3 часа', 22, 4.9, 1284, 'Хит продаж', 'RU · EN · KY', array['https://images.unsplash.com/photo-1506905925346-21bda4d32df4?w=900&q=80']::text[], 40.5275, 72.7985, true, 'до 12 человек', 'Главный вход на Сулайман-Тоо', 'Подъём до рассвета, пещеры, петроглифы и вид на Ферганскую долину. Гиды — из Оша, не приезжие шаблоны.', array['Священная гора ЮНЕСКО', 'Рассвет над долиной', 'Истории паломников']::text[], array['Лицензированный гид', 'Входной билет', 'Вода']::text[], '{"en":{"title":"Sunrise on Sulaiman-Too with a local guide","type":"Tour","place":"Sulaiman-Too","badge":"Bestseller","group":"up to 12 people","meeting":"Main entrance to Sulaiman-Too","description":"Climb before dawn: caves, petroglyphs and a view over the Fergana Valley. Guides are from Osh, not scripted visitors.","highlights":["Sacred UNESCO mountain","Sunrise over the valley","Pilgrims'' stories"],"includes":["Licensed guide","Entrance ticket","Water"]}}'::jsonb, true, 40),
  ('bazaar', 'food', 'Гастротур', 'Джайма: рынок с дегустацией специй', 'Базар Джайма', '2 часа', 19, 4.8, 756, 'Рядом с центром', 'RU · EN', array['https://images.unsplash.com/photo-1532336414038-cf19250c5757?w=900&q=80']::text[], 40.5233, 72.7969, true, 'до 8 человек', 'Главные ворота базара Джайма', 'Самса, курут, халва, ряды специй. Гид научит торговаться и не брать туристическую наценку.', array['5 дегустаций', 'Как выбирать сухофрукты', 'Скрытые ряды']::text[], array['Гид', 'Дегустации', 'Чай в чайхане']::text[], '{"en":{"title":"Jayma Bazaar with a spice tasting","type":"Food tour","place":"Jayma Bazaar","badge":"Near the center","group":"up to 8 people","meeting":"Main gate of Jayma Bazaar","description":"Samsa, kurut, halva, rows of spices. Your guide teaches you to bargain and skip the tourist markup.","highlights":["5 tastings","How to pick dried fruit","Hidden rows"],"includes":["Guide","Tastings","Tea at a chaikhana"]}}'::jsonb, true, 50),
  ('mosque', 'culture', 'Экскурсия', 'Мечеть Равзат и исламская архитектура Оша', 'Мечеть Равзат', '1.5 часа', 12, 4.6, 321, null, 'RU · KY', array['https://images.unsplash.com/photo-1564769625905-50e93615b405?w=900&q=80']::text[], 40.526, 72.794, true, 'до 15 человек', 'Площадь перед мечетью Равзат', 'Спокойный маршрут по архитектуре и этикету. Платок для женщин выдаём на месте.', array['Архитектура и орнамент', 'Правила посещения', 'Коротко и по делу']::text[], array['Гид', 'Платок при необходимости']::text[], '{"en":{"title":"Ravzat Mosque and Islamic architecture of Osh","type":"Tour","place":"Ravzat Mosque","group":"up to 15 people","meeting":"Square in front of Ravzat Mosque","description":"A calm walk through architecture and etiquette. Headscarves for women are provided on site.","highlights":["Architecture and ornament","Visiting etiquette","Short and to the point"],"includes":["Guide","Headscarf if needed"]}}'::jsonb, true, 60),
  ('akbuura', 'nature', 'Прогулка', 'Рассветная прогулка вдоль Ак-Бууры', 'Река Ак-Буура', '2 часа', 14, 4.7, 204, 'На свежем воздухе', 'RU', array['https://images.unsplash.com/photo-1432405972618-c60b0225b8f9?w=900&q=80']::text[], 40.518, 72.81, true, 'до 10 человек', 'Мост у парка', 'Тихий маршрут по берегу: мосты, птицы, утро города. Подходит, если не хотите крутой подъём.', array['Ровный маршрут', 'Фото у реки', 'Местный завтрак-опция']::text[], array['Гид', 'Маршрут 3 км']::text[], '{"en":{"title":"Sunrise walk along the Ak-Buura river","type":"Walk","place":"Ak-Buura River","badge":"Outdoors","group":"up to 10 people","meeting":"Bridge by the park","description":"A quiet riverside route: bridges, birds, the city waking up. Good if you''d rather skip a steep climb.","highlights":["Flat route","Photos by the river","Optional local breakfast"],"includes":["Guide","3 km route"]}}'::jsonb, true, 70),
  ('oldtown', 'tours', 'Экскурсия', 'Пеший гид по Старому городу', 'Старый город', '2.5 часа', 17, 4.8, 540, 'Бесплатная отмена', 'RU · EN', array['https://images.unsplash.com/photo-1526772662000-3f88f10405ff?w=900&q=80']::text[], 40.5288, 72.7905, true, 'до 12 человек', 'Чайхана у восточных ворот', 'Дворы, дома старше века, чайхана. Гиды рассказывают семейные истории, а не википедию.', array['Жилые дворы', 'Чай в конце', 'Малые группы']::text[], array['Гид', 'Чай']::text[], '{"en":{"title":"Old Town walking tour","type":"Tour","place":"Old Town","badge":"Free cancellation","group":"up to 12 people","meeting":"Chaikhana by the east gate","description":"Courtyards, century-old houses, a chaikhana. Guides share family stories, not Wikipedia.","highlights":["Residential courtyards","Tea at the end","Small groups"],"includes":["Guide","Tea"]}}'::jsonb, true, 80)
on conflict (id) do update set
  category = excluded.category, type = excluded.type, title = excluded.title, place = excluded.place,
  duration = excluded.duration, price = excluded.price, rating = excluded.rating, reviews = excluded.reviews,
  badge = excluded.badge, langs = excluded.langs, images = excluded.images, lat = excluded.lat, lng = excluded.lng,
  free_cancel = excluded.free_cancel, group_size = excluded.group_size, meeting = excluded.meeting,
  description = excluded.description, highlights = excluded.highlights, includes = excluded.includes,
  i18n = excluded.i18n, published = excluded.published, sort = excluded.sort;

insert into public.facts
  (id, title, emoji, short, image, tag, body, points, link_label, link_tab, exp_id, i18n, published, sort)
values
  ('older-than-rome', 'Город старше Рима', '🏛️', 'Археологические находки на склонах Сулайман-Тоо подтверждают свыше 3000 лет непрерывной городской истории.', 'https://images.unsplash.com/photo-1506905925346-21bda4d32df4?w=1200&q=85', 'История', array['Ош считается одним из древнейших городов Центральной Азии: на склонах и у подножия Сулайман-Тоо найдены следы поселений эпохи бронзы — это более трёх тысяч лет непрерывной городской жизни.', 'Город вырос на пересечении ферганских торговых путей: здесь останавливались караваны, шедшие из Кашгара в Самарканд, и именно торговля сформировала характер ошских базаров, которые работают на тех же местах до сих пор.']::text[], array['Сулайман-Тоо — объект Всемирного наследия ЮНЕСКО (с 2009 года)', 'На горе более 100 мест наскальных рисунков и культовых площадок', 'Музей внутри горы устроен в естественной пещере']::text[], 'Посмотреть туры по Сулайман-Тоо', 'tours', 'sulaiman', '{"en":{"title":"A city older than Rome","short":"Archaeological finds on the slopes of Sulaiman-Too point to more than 3,000 years of continuous urban history.","tag":"History","body":["Osh is considered one of the oldest cities in Central Asia: Bronze Age settlement traces have been found on the slopes and at the foot of Sulaiman-Too — more than three thousand years of continuous city life.","The city grew at a crossroads of Fergana trade routes: caravans travelling from Kashgar to Samarkand stopped here, and trade shaped the character of the Osh bazaars, which still operate in the same places today."],"points":["Sulaiman-Too has been a UNESCO World Heritage Site since 2009","The mountain has over 100 sites with petroglyphs and places of worship","A museum inside the mountain occupies a natural cave"],"linkLabel":"See Sulaiman-Too tours"}}'::jsonb, true, 10),
  ('devzira', 'Легендарный рис Девзира', '🍚', 'Главный сорт для ошского плова выращивают на местных полях Ферганской долины.', 'https://images.unsplash.com/photo-1512058564366-18510be2db19?w=1200&q=85', 'Кухня', array['Девзира — розовато-коричневый рис с плотным зерном, который выращивают в Ферганской долине. Именно он даёт ошскому плову характерную рассыпчатость: зерно впитывает бульон, но не разваривается.', 'На базаре Девзиру узнают по мучному налёту и продольной бороздке: продавцы предлагают потереть зерно в ладонях — настоящий рис слегка скрипит и оставляет светлую пыль.']::text[], array['Рис вызревает дольше обычного — отсюда цена выше', 'Перед готовкой его промывают и замачивают в тёплой солёной воде', 'Ошский плов готовят на курдючном сале, морковь кладут двумя слоями']::text[], 'Кулинарные практики Оша', 'tours', 'cooking', '{"en":{"title":"The legendary Devzira rice","short":"The key rice for Osh plov is grown in local fields of the Fergana Valley.","tag":"Cuisine","body":["Devzira is a pinkish-brown, firm-grained rice grown in the Fergana Valley. It gives Osh plov its signature fluffiness: the grain soaks up the broth without turning mushy.","At the bazaar you can spot Devzira by its powdery coating and a groove along the grain. Sellers invite you to rub it between your palms — real Devzira squeaks a little and leaves a light dust."],"points":["It ripens longer than ordinary rice — hence the higher price","Before cooking it is rinsed and soaked in warm salted water","Osh plov is cooked in tail fat, with carrots laid in two layers"],"linkLabel":"Cooking classes in Osh"}}'::jsonb, true, 20),
  ('jaima-bazaar', 'Базар, которому тысячи лет', '🧺', 'Базар Джайма тянется вдоль реки Ак-Буура и остаётся одним из крупнейших рынков Центральной Азии.', 'https://images.unsplash.com/photo-1567696911980-2eed69a46042?w=1200&q=85', 'Традиции', array['Джайма — не туристическая декорация, а живой рынок, который работает на берегу Ак-Бууры много столетий. Ряды растянуты почти на километр: специи, сухофрукты, ножи, тюбетейки, ткани, конская упряжь.', 'Лучшее время — утро до 11:00: ещё прохладно, товар свежий, а торговцы охотнее угощают и рассказывают. Торг здесь — часть этикета, но вести его принято спокойно и с улыбкой.']::text[], array['Ножи ручной ковки — один из главных местных сувениров', 'Курут, урюк и грецкий орех продают на вес, пробовать можно бесплатно', 'Оплата чаще наличными в сомах — карту принимают не везде']::text[], 'Экскурсии по базару', 'tours', 'bazaar', '{"en":{"title":"A bazaar thousands of years old","short":"Jayma Bazaar stretches along the Ak-Buura river and remains one of the largest markets in Central Asia.","tag":"Traditions","body":["Jayma isn''t a tourist set — it''s a living market that has traded on the banks of the Ak-Buura for centuries. The rows run for almost a kilometre: spices, dried fruit, knives, skullcaps, fabrics, horse tack.","The best time is the morning before 11:00: it''s still cool, the goods are fresh, and traders are happier to offer a taste and chat. Bargaining is part of the etiquette, but it''s done calmly and with a smile."],"points":["Hand-forged knives are one of the top local souvenirs","Kurut, dried apricots and walnuts are sold by weight — tasting is free","Cash in som is usual — cards aren''t accepted everywhere"],"linkLabel":"Bazaar tours"}}'::jsonb, true, 30),
  ('silk-road-crossroads', 'Перекрёсток Шёлкового пути', '🐪', 'Через Ош проходила северная ветка Великого шёлкового пути в Ферганскую долину.', 'https://images.unsplash.com/photo-1528181304800-259b08848526?w=1200&q=85', 'Шёлковый путь', array['Ош лежал на ответвлении Великого шёлкового пути, связывавшем Кашгар с Ферганой и далее с Самаркандом и Бухарой. Караваны шли через горные перевалы, и город служил последней большой остановкой перед подъёмом в Алайские горы.', 'Этот транзит оставил городу многоязычие, ремесленные кварталы и кухню, в которой уживаются уйгурский лагман, узбекская самса и кыргызский бешбармак.']::text[], array['Отсюда начинается Памирский тракт — дорога к перевалам Алая', 'В Старом городе сохранились кварталы ремесленников', 'Город исторически двуязычный: кыргызский и узбекский']::text[], 'Собрать маршрут по городу', 'route', null, '{"en":{"title":"A Silk Road crossroads","short":"A northern branch of the Great Silk Road ran through Osh into the Fergana Valley.","tag":"Silk Road","body":["Osh lay on a branch of the Great Silk Road linking Kashgar with Fergana and on to Samarkand and Bukhara. Caravans crossed mountain passes, and the city was the last big stop before the climb into the Alay Mountains.","That transit left the city its many languages, craft quarters and a cuisine where Uyghur lagman, Uzbek samsa and Kyrgyz beshbarmak sit side by side."],"points":["The Pamir Highway starts here — the road to the Alay passes","Craft quarters survive in the Old Town","The city is historically bilingual: Kyrgyz and Uzbek"],"linkLabel":"Plan a route around the city"}}'::jsonb, true, 40)
on conflict (id) do update set
  title = excluded.title, emoji = excluded.emoji, short = excluded.short, image = excluded.image,
  tag = excluded.tag, body = excluded.body, points = excluded.points, link_label = excluded.link_label,
  link_tab = excluded.link_tab, exp_id = excluded.exp_id, i18n = excluded.i18n,
  published = excluded.published, sort = excluded.sort;
